export function render(container: HTMLElement) {
  const holdings = CoreEngine.dataStore.holdings;
  if (holdings.length === 0) {
    container.innerHTML = '<div style="text-align:center;padding:20px;color:#888;font-size:0.8rem">No holdings yet. Add one by clicking the "Add Holding" button.</div>';
    return;
  }

  const totalValue = holdings.reduce((sum, h) => sum + h.quantity * h.price, 0);
  const totalValueEl = document.createElement('div');
  totalValueEl.textContent = `$${totalValue.toFixed(2)}`;
  totalValueEl.style.fontSize = '2rem';
  totalValueEl.style.fontWeight = 'bold';
  totalValueEl.style.color = '#4ade80';
  container.appendChild(totalValueEl);

  const searchInput = document.createElement('input');
  searchInput.type = 'search';
  searchInput.placeholder = 'Search holdings...';
  searchInput.oninput = (e) => {
    const value = (e.target as HTMLInputElement).value.toLowerCase();
    const filtered = holdings.filter((h) =>
      h.symbol.toLowerCase() + h.name.toLowerCase() + h.quantity.toString() + h.price.toString().toLowerCase().includes(value)
    );
    updateList(filtered);
  };
  container.appendChild(searchInput);

  const list = document.createElement('div');
  list.style.display = 'flex';
  list.style.flexDirection = 'column';
  list.style.gap = '8px';
  container.appendChild(list);

  function updateList(filtered: Holding[]) {
    list.innerHTML = '';
    filtered.forEach((h) => {
      const card = document.createElement('div');
      card.className = 'card';
      card.style.background = '#15152a';
      card.style.border = '1px solid rgba(255,255,255,0.1)';
      card.style.borderRadius = '12px';
      card.style.padding = '16px';
      card.style.minWidth = '250px';
      card.style.flexShrink = '0';
      card.style.boxShadow = '0 4px 12px rgba(0,0,0,0.3)';

      const name = document.createElement('h3');
      name.textContent = h.name;
      name.style.color = '#e0e0e0';
      name.style.fontSize = '1rem';
      card.appendChild(name);

      const symbol = document.createElement('p');
      symbol.textContent = h.symbol;
      symbol.style.color = '#888';
      symbol.style.fontSize = '0.8rem';
      card.appendChild(symbol);

      const price = document.createElement('p');
      price.textContent = `$${h.price.toFixed(2)}`;
      price.style.color = '#4ade80';
      price.style.fontSize = '0.85rem';
      card.appendChild(price);

      const quantity = document.createElement('p');
      quantity.textContent = h.quantity;
      quantity.style.color = '#888';
      quantity.style.fontSize = '0.8rem';
      card.appendChild(quantity);

      const value = document.createElement('p');
      value.textContent = `$${(h.quantity * h.price).toFixed(2)}`;
      value.style.color = '#4ade80';
      value.style.fontSize = '0.85rem';
      card.appendChild(value);

      const actions = document.createElement('div');
      actions.style.display = 'flex';
      actions.style.gap = '8px';
      actions.style.marginTop = '8px';
      card.appendChild(actions);

      const editBtn = document.createElement('button');
      editBtn.textContent = 'Edit';
      editBtn.style.backgroundColor = '#00d9ff';
      editBtn.style.color = '#fff';
      editBtn.style.padding = '4px 8px';
      editBtn.style.border = 'none';
      editBtn.style.borderRadius = '4px';
      editBtn.style.cursor = 'pointer';
      editBtn.onclick = () => { editHolding(h); };
      actions.appendChild(editBtn);

      const deleteBtn = document.createElement('button');
      deleteBtn.textContent = 'Delete';
      deleteBtn.style.backgroundColor = '#f87171';
      deleteBtn.style.color = '#fff';
      deleteBtn.style.padding = '4px 8px';
      deleteBtn.style.border = 'none';
      deleteBtn.style.borderRadius = '4px';
      deleteBtn.style.cursor = 'pointer';
      deleteBtn.onclick = () => { deleteHolding(h.id); };
      actions.appendChild(deleteBtn);

      list.appendChild(card);
    });
  }

  const holdingsList = holdings.filter((h) =>
    h.symbol.toLowerCase() + h.name.toLowerCase() + h.quantity.toString() + h.price.toString().toLowerCase().includes(searchInput.value.toLowerCase())
  );
  updateList(holdingsList);
}

