import async, { InputHandler } from '../input-handler/input-handler.ts';

export class DataStore {
  private transactions: { id: string; symbol: string; quantity: number; price: number; date: string }[];

  constructor() {
    this.transactions = [];
  }

  public addTransaction(transaction: { symbol: string; quantity: number; price: number; date: string }): void {
    const id = Date.now().toString() + Math.random().toString(36).slice(2, 10);
    this.transactions.push({ id, ...transaction });
  }

  public getTransactions(): { id: string; symbol: string; quantity: number; price: number; date: string }[] {
    return this.transactions;
  }

  public removeTransaction(id: string): void {
    this.transactions = this.transactions.filter(t => t.id !== id);
  }

  public updateTransaction(id: string, updates: Partial<{ symbol: string; quantity: number; price: number; date: string }>): void {
    this.transactions = this.transactions.map(t => t.id === id ? { ...t, ...updates } : t);
  }
}

