export class LedgerStore {
  private transactions: Record<string, { id: string; symbol: string; quantity: number; price: number; date: string }>;

  constructor() {
    this.transactions = {};
  }

  public addTransaction(request: { symbol: string; quantity: number; price: number; date: string }): void {
    const id = Date.now().toString() + Math.random().toString(36).slice(2, 10);
    this.transactions[id] = { id, ...request };
  }

  public getTransactions(): { id: string; symbol: string; quantity: number; price: number; date: string }[] {
    return Object.values(this.transactions);
  }
}
